"""Tests for bump_main_version.py. They run on throwaway git repositories, never
the real tree, so main's own version moves never break them."""

import importlib.util
import json
import os
import subprocess
import sys
import tempfile
import unittest
from pathlib import Path

SCRIPT = Path(__file__).with_name("bump_main_version.py")
_spec = importlib.util.spec_from_file_location("bump_main_version", SCRIPT)
bump = importlib.util.module_from_spec(_spec)
_spec.loader.exec_module(bump)

CHART_DIR = "deploy/helm/charts/platform"
OPERATOR_CHART = f"{CHART_DIR}/components/operator/Chart.yaml"
# A hook run by `git commit` inherits variables such as GIT_INDEX_FILE, which
# would point the throwaway repositories' git calls at the real index.
CLEAN_ENV = {k: v for k, v in os.environ.items() if not k.startswith("GIT_")}


def workspace_cargo(version, comment=""):
    return f"""[workspace]
members = ["lib/llm"]

[workspace.package]
version = "{version}"{comment}
edition = "2021"

[workspace.dependencies]
dynamo-llm = {{ path = "lib/llm", version = "{version}" }}
backon = {{ version = "1.6.0" }}
timerfd = "1.6.0"
"""


def lock(version):
    return f"""# This file is automatically @generated by Cargo.
version = 4

[[package]]
name = "backon"
version = "1.6.0"
source = "registry+https://github.com/rust-lang/crates.io-index"
checksum = "abc"

[[package]]
name = "dynamo-llm"
version = "{version}"
dependencies = [
 "backon",
]

[[package]]
name = "forked"
version = "1.6.0"
source = "git+https://github.com/example/forked?rev=1#1"
"""


def platform_chart(version, pin):
    return f"""apiVersion: v2
name: dynamo-platform
version: {version}
dependencies:
  - name: dynamo-operator
    version: {pin}
    repository: file://components/operator
    condition: dynamo-operator.enabled
  - name: nats
    version: 1.6.0
    repository: https://nats-io.github.io/k8s/helm/charts/
"""


def operator_chart(version, app):
    return f"""apiVersion: v2
name: dynamo-operator
version: {version}
appVersion: "{app}"
"""


def readme(version):
    return f"""![Version: {version}](https://img.shields.io/badge/Version-{version}-informational?style=flat-square)

### v1.6.0

Upgrade the operator to Dynamo 1.6.0 or later.

| Repository | Name | Version |
|------------|------|---------|
| file://components/operator | dynamo-operator | {version} |
| https://nats-io.github.io/k8s/helm/charts/ | nats | 1.6.0 |
"""


class Repo:
    def __init__(self, version="1.6.0", **overrides):
        self._tmp = tempfile.TemporaryDirectory()
        self.root = Path(self._tmp.name)
        files = {
            "Cargo.toml": workspace_cargo(version),
            "Cargo.lock": lock(version),
            "lib/llm/Cargo.toml": '[package]\nname = "dynamo-llm"\n'
            "version.workspace = true\n",
            "pyproject.toml": f'[project]\nname = "ai-dynamo"\nversion = "{version}"\n'
            f'dependencies = ["ai-dynamo-runtime=={version}", "somepkg==1.6.0",'
            f' "ai-dynamo-extra=={version}.dev1"]\n',
            "benchmarks/pyproject.toml": '[project]\nversion = "0.1.0"\n',
            f"{CHART_DIR}/Chart.yaml": platform_chart(version, version),
            OPERATOR_CHART: operator_chart(version, version),
            f"{CHART_DIR}/README.md": readme(version),
            "deploy/helm/charts/power-agent/Chart.yaml": f"version: {version}\n",
        }
        files.update(overrides)
        for rel, text in files.items():
            path = self.root / rel
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_text(text)
        # Matches a target pattern but stays untracked, so it must not move.
        (self.root / "scratch").mkdir()
        (self.root / "scratch/pyproject.toml").write_text(f'version = "{version}"\n')
        for git in (["git", "init", "-q"], ["git", "add", "--", *files]):
            subprocess.run(git, cwd=self.root, env=CLEAN_ENV, check=True)

    def call(self, command, release):
        return subprocess.run(
            [sys.executable, str(SCRIPT), command, "--release-version", release]
            + ["--root", str(self.root)],
            env=CLEAN_ENV,
            capture_output=True,
            text=True,
        )

    def run(self, command, release):
        proc = self.call(command, release)
        if proc.returncode:
            raise AssertionError(f"exit {proc.returncode}: {proc.stderr}")
        return json.loads(proc.stdout)

    def read(self, rel):
        return (self.root / rel).read_text()

    def close(self):
        self._tmp.cleanup()


class VersionTest(unittest.TestCase):
    def test_next_minor(self):
        cases = {
            "1.6.0": "1.7.0",
            "1.6.2": "1.7.0",
            "1.9.0": "1.10.0",
            "2.0.0": "2.1.0",
        }
        for release, target in cases.items():
            with self.subTest(release=release):
                self.assertEqual(bump.next_minor(release), target)

    def test_rejects_non_stable_versions(self):
        for bad in ["1.6", "v1.6.0", "1.6.0-dev.1", "1.6.0.post1", ""]:
            with self.subTest(bad=bad), self.assertRaises(SystemExit):
                bump.next_minor(bad)

    def test_compares_numerically(self):
        self.assertLess(bump.parse("1.9.0"), bump.parse("1.10.0"))


class PickReleaseTest(unittest.TestCase):
    def ls_remote(self, *branches):
        return "".join(
            f"{i:040x}\trefs/heads/release/{b}\n" for i, b in enumerate(branches)
        )

    def test_newest_stable_branch_wins_numerically(self):
        out = self.ls_remote("1.9.0", "1.10.0", "1.10.1", "1.4.2")
        self.assertEqual(bump.pick_release(out), "1.10.1")

    def test_prerelease_and_named_branches_are_ignored(self):
        out = self.ls_remote("1.6.1", "1.8.0-dev.1", "1.7.0.post1", "1.7.0-model-x")
        self.assertEqual(bump.pick_release(out), "1.6.1")

    def test_no_release_branch_is_an_error(self):
        with self.assertRaises(SystemExit):
            bump.pick_release(self.ls_remote("1.8.0-dev.1"))


class NeedsBumpTest(unittest.TestCase):
    def test_decisions(self):
        cases = [
            ("1.6.0", "1.6.0", True),
            ("1.6.0", "1.6.1", True),  # patch cut before the bump merged
            ("1.7.0", "1.6.1", False),
            ("1.7.0", "1.6.2", False),
            ("1.7.0", "1.7.0", True),
            ("1.8.0", "1.6.3", False),  # late patch of an old line
            ("1.9.0", "1.9.0", True),
        ]
        for main, release, needed in cases:
            with self.subTest(main=main, release=release):
                self.assertIs(bump.needs_bump(main, release), needed)

    def test_off_line_cuts_exit_for_a_human(self):
        for main, release in [
            ("1.6.0", "1.7.0"),  # skipped minor
            ("1.5.0", "1.6.0"),  # main was never bumped for the 1.5 line
            ("1.9.0", "2.0.0"),  # major cut
            ("1.6.0", "9.9.9"),  # stray branch
        ]:
            with self.subTest(main=main, release=release):
                with self.assertRaises(SystemExit):
                    bump.needs_bump(main, release)


class PlanTest(unittest.TestCase):
    def test_plan_reports_and_never_writes(self):
        repo = Repo("1.6.0")
        try:
            before = {p: repo.read(p) for p in ("Cargo.toml", "Cargo.lock")}
            result = repo.run("plan", "1.6.1")
            self.assertEqual(
                result,
                {
                    "release": "1.6.1",
                    "current": "1.6.0",
                    "target": "1.7.0",
                    "bump_needed": True,
                    "operator_app_version": "1.6.0",
                },
            )
            for path, text in before.items():
                self.assertEqual(repo.read(path), text)
        finally:
            repo.close()

    def test_apply_is_idempotent(self):
        repo = Repo("1.6.0")
        try:
            self.assertTrue(repo.run("apply", "1.6.0")["changed"])
            again = repo.run("apply", "1.6.0")
            self.assertEqual(again["current"], "1.7.0")
            self.assertFalse(again["bump_needed"])
            self.assertNotIn("changed", again)
        finally:
            repo.close()


class ApplyTest(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        cls.repo = Repo("1.6.0")
        cls.result = cls.repo.run("apply", "1.6.0")

    @classmethod
    def tearDownClass(cls):
        cls.repo.close()

    def test_workspace_and_path_dependency_move(self):
        text = self.repo.read("Cargo.toml")
        self.assertIn('[workspace.package]\nversion = "1.7.0"', text)
        self.assertIn('dynamo-llm = { path = "lib/llm", version = "1.7.0" }', text)

    def test_registry_dependencies_at_the_same_version_stay(self):
        text = self.repo.read("Cargo.toml")
        self.assertIn('backon = { version = "1.6.0" }', text)
        self.assertIn('timerfd = "1.6.0"', text)

    def test_lock_moves_only_workspace_crates(self):
        text = self.repo.read("Cargo.lock")
        self.assertIn('name = "dynamo-llm"\nversion = "1.7.0"', text)
        self.assertIn('name = "backon"\nversion = "1.6.0"', text)
        self.assertIn('name = "forked"\nversion = "1.6.0"', text)
        self.assertIn("version = 4\n", text)  # lock format line untouched

    def test_pyproject_moves_own_version_and_exact_dynamo_pins_only(self):
        text = self.repo.read("pyproject.toml")
        self.assertIn('version = "1.7.0"', text)
        self.assertIn('"ai-dynamo-runtime==1.7.0"', text)
        self.assertIn('"somepkg==1.6.0"', text)
        self.assertIn('"ai-dynamo-extra==1.6.0.dev1"', text)
        self.assertEqual(
            self.repo.read("benchmarks/pyproject.toml"),
            '[project]\nversion = "0.1.0"\n',
        )

    def test_platform_chart_and_operator_pin_move(self):
        text = self.repo.read(f"{CHART_DIR}/Chart.yaml")
        self.assertIn("name: dynamo-platform\nversion: 1.7.0\n", text)
        self.assertIn("- name: dynamo-operator\n    version: 1.7.0\n", text)

    def test_third_party_chart_pin_at_the_same_version_stays(self):
        text = self.repo.read(f"{CHART_DIR}/Chart.yaml")
        self.assertIn("- name: nats\n    version: 1.6.0\n", text)

    def test_operator_chart_version_moves_but_app_version_waits(self):
        self.assertEqual(
            self.repo.read(OPERATOR_CHART), operator_chart("1.7.0", "1.6.0")
        )

    def test_readme_moves_badge_and_local_row_only(self):
        text = self.repo.read(f"{CHART_DIR}/README.md")
        self.assertIn("![Version: 1.7.0](", text)
        self.assertIn("badge/Version-1.7.0-", text)
        self.assertIn("| file://components/operator | dynamo-operator | 1.7.0 |", text)
        self.assertIn("| nats | 1.6.0 |", text)
        self.assertIn("### v1.6.0\n", text)
        self.assertIn("Dynamo 1.6.0 or later", text)

    def test_files_outside_the_scope_stay(self):
        self.assertEqual(
            self.repo.read("deploy/helm/charts/power-agent/Chart.yaml"),
            "version: 1.6.0\n",
        )
        self.assertEqual(
            self.repo.read("scratch/pyproject.toml"), 'version = "1.6.0"\n'
        )

    def test_reports_every_changed_file(self):
        self.assertEqual(
            self.result["changed"],
            sorted(
                [
                    "Cargo.lock",
                    "Cargo.toml",
                    "pyproject.toml",
                    f"{CHART_DIR}/Chart.yaml",
                    f"{CHART_DIR}/README.md",
                    OPERATOR_CHART,
                ]
            ),
        )


class SafetyTest(unittest.TestCase):
    def assert_apply_fails(self, message, **overrides):
        repo = Repo("1.6.0", **overrides)
        try:
            before = repo.read("Cargo.lock")
            proc = repo.call("apply", "1.6.0")
            self.assertNotEqual(proc.returncode, 0)
            self.assertIn(message, proc.stderr)
            return repo.read("Cargo.lock") != before
        finally:
            repo.close()

    def test_operator_pin_not_at_main_version(self):
        wrote = self.assert_apply_fails(
            "dynamo-operator dependency pin",
            **{f"{CHART_DIR}/Chart.yaml": platform_chart("1.6.0", "1.5.0")},
        )
        self.assertFalse(wrote, "a refused bump must not leave edits behind")

    def test_quoted_operator_pin(self):
        self.assert_apply_fails(
            "dynamo-operator dependency pin",
            **{f"{CHART_DIR}/Chart.yaml": platform_chart("1.6.0", '"1.6.0"')},
        )

    def test_workspace_version_the_rewrite_cannot_reach(self):
        wrote = self.assert_apply_fails(
            "Cargo.toml would still read 1.6.0",
            **{"Cargo.toml": workspace_cargo("1.6.0", comment="  # main")},
        )
        self.assertFalse(wrote, "a refused bump must not leave edits behind")


if __name__ == "__main__":
    unittest.main()
